import { useState, useEffect } from "react";
import EntityCard from "./components/EntityCard";
import AddEntityForm from "./components/AddEntityForm";
import EditEntityForm from "./components/EditEntityForm";
import { getEntities, createEntity, updateEntity, deleteEntity } from "./api/entities";

function App() {
    const [entities, setEntities] = useState([]);
    const [editingEntity, setEditingEntity] = useState(null);

    useEffect(() => {
        getEntities().then(data => setEntities(data));
    }, []);

    const handleAdd = (title) => {
        createEntity({ title, body: "" })
            .then(newEntity => setEntities(prev => [...prev, newEntity]));
    };

    const handleDelete = (id) => {
        deleteEntity(id)
            .then(() => setEntities(prev => prev.filter(e => e.id !== id)));
    };

    const handleSave = (id, title) => {
        updateEntity(id, { title, body: "" })
            .then(updated => {
                setEntities(prev => prev.map(e => e.id === id ? updated : e));
                setEditingEntity(null);
            });
    };

    return (
        <div className="container mt-4">
            <h1 className="mb-4">Entities</h1>

            <AddEntityForm onAdd={handleAdd} />

            {editingEntity && (
                <EditEntityForm
                    entity={editingEntity}
                    onSave={handleSave}
                    onCancel={() => setEditingEntity(null)}
                />
            )}

            <div className="row">
                {entities.map(entity => (
                    <div className="col-md-4" key={entity.id}>
                        <EntityCard
                            entity={entity}
                            onEdit={setEditingEntity}
                            onDelete={handleDelete}
                        />
                    </div>
                ))}
            </div>
        </div>
    );
}

export default App;
